# The following code is used to generate the summary of the text
def generate_summary(text):
    summary = []
    for i in range(0, len(text)):
        if text[i] =='':
            summary.append(text[i])
            continue
        if text[i] == '.':
            summary.append(text[i])
            continue
        if text[i] == ',':
            summary.append(text[i])
            continue

